import{_ as l,o as t,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2016-OCT-12 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-OCT-12 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph","BlueStore","Performance Optimization","RocksDB","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.md"};function a(s,e,n,p,g,_){return t(),o("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Ramesh, Dan Lambright, Kevin, Alan, Sage, Tim, 等</p><p><strong>会议主题</strong>： Ceph分布式存储系统，特别是BlueStore的性能优化</p><p><strong>会议内容</strong>：</p><p><strong>一、本周工作进展</strong></p><ol><li><strong>Ramesh</strong> 优化了内存数据库存储接口，将键值存储从B树实现切换到通用映射，以提高性能。</li><li><strong>Dan Lambright</strong> 尝试使用Ceph的PG映射功能，为PG信息提供了一种新的实现方式，有望提高性能。</li><li><strong>BlueStore性能优化</strong>： <ul><li>通过减少内存结构的大小，降低对缓存节点的内存需求，本周关闭了许多与BlueStore相关的请求。</li><li>Sage提出了一种更新PG信息的方法，显著减少了数据写入量和提高了性能。</li><li>Tim试图将快速编码功能合并到BlueStore中，但遇到了冲突。</li></ul></li></ol><p><strong>二、讨论议题</strong></p><ol><li><p><strong>BlueStore与文件存储的对比</strong>：</p><ul><li>BlueStore在随机读取方面存在性能问题，尤其是在IOPS大小为32时。</li><li>Sage提出了可能的解决方案，包括异步支持一次从Ceph MO数据结构中检索多个扩展，以及进行序列化操作。</li><li>讨论了异步消息传递和快速调度器，以提高性能。</li></ul></li><li><p><strong>RocksDB的写前日志（WAL）优化</strong>：</p><ul><li>目前测试实验室出现问题，无法进行长时间测试。</li><li>初步结果显示，增加日志数量或日志大小可以提高性能。</li><li>需要进一步研究如何区分WAL数据与元数据，以及如何量化这些行为。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>Ramesh正在研究将键值存储从B树实现切换到通用映射。</li><li>Dan Lambright正在尝试使用Ceph的PG映射功能。</li><li>Sage正在研究改进BlueStore的随机写入性能。</li></ul></li></ol><p><strong>三、决定事项</strong></p><ol><li>继续关注BlueStore的性能优化，特别是随机读取和序列读取性能问题。</li><li>进一步研究RocksDB的WAL优化，包括增加日志数量或日志大小。</li><li>完成Ramesh和Dan Lambright的工作，以提高性能。</li><li>Sage继续研究改进BlueStore的随机写入性能。</li></ol><p><strong>四、后续行动计划</strong></p><ol><li>Ramesh和Dan Lambright继续进行相关工作。</li><li>Sage研究改进BlueStore的随机写入性能。</li><li>Tim解决快速编码功能的合并冲突。</li><li>Kevin继续研究减少内存结构大小的工作。</li></ol><p><strong>五、其他</strong></p><ol><li>讨论了BlueStore的分配策略，以及如何减少写放大和压缩。</li><li>讨论了如何使用RocksDB的WAL来提高性能。</li><li>讨论了如何使用更多的工具和指标来分析Ceph的性能。</li></ol>',15)])])}const h=l(r,[["render",a]]);export{u as __pageData,h as default};
